"use client";

import { Tooltip } from "@base-ui/react/tooltip";
import { type ComponentPropsWithoutRef, type ReactNode, forwardRef } from "react";
import { InspectorField, InspectorFieldLabel, InspectorFieldSelect } from "@/components/ui/inspector-field";
import { usePlaybackControls } from "./playback-controls-state";
import { cn } from "@/lib/utils";

type PartProps = Omit<ComponentPropsWithoutRef<"button">, "children" | "aria-label" | "aria-pressed">;
type ButtonProps = PartProps & { label: string; icon: ReactNode; pressed?: boolean };

export const line = (path: string, className?: string) => (
  <svg aria-hidden viewBox="0 0 16 16" className={className} fill="none" stroke="currentColor" strokeWidth={1.5} strokeLinecap="round" strokeLinejoin="round">
    <path d={path} />
  </svg>
);
export const solid = (path: string) => (
  <svg aria-hidden viewBox="0 0 16 16" fill="currentColor">
    <path d={path} />
  </svg>
);

const icons = {
  play: solid("M5 3.2v9.6c0 .4.4.6.8.4l7.2-4.8a.5.5 0 0 0 0-.8L5.8 2.8c-.4-.2-.8 0-.8.4Z"),
  pause: solid("M4.5 3h2v10h-2a.5.5 0 0 1-.5-.5v-9a.5.5 0 0 1 .5-.5Zm5 0h2a.5.5 0 0 1 .5.5v9a.5.5 0 0 1-.5.5h-2V3Z"),
  replay: line("M3 8a5 5 0 1 0 1.5-3.6L3 5.8M3 2.8v3h3"),
  restart: solid("M3 3.2h1.6v9.6H3ZM13 3.8v8.4a.5.5 0 0 1-.8.4L6.3 8.4a.5.5 0 0 1 0-.8l5.9-4.2a.5.5 0 0 1 .8.4Z"),
  rewind: solid("M8 4v8a.5.5 0 0 1-.8.4l-5.3-4a.5.5 0 0 1 0-.8l5.3-4A.5.5 0 0 1 8 4Zm6.5 0v8a.5.5 0 0 1-.8.4l-5.3-4a.5.5 0 0 1 0-.8l5.3-4a.5.5 0 0 1 .8.4Z"),
  fastForward: solid("M1.5 4v8a.5.5 0 0 0 .8.4l5.3-4a.5.5 0 0 0 0-.8l-5.3-4a.5.5 0 0 0-.8.4ZM8 4v8a.5.5 0 0 0 .8.4l5.3-4a.5.5 0 0 0 0-.8l-5.3-4A.5.5 0 0 0 8 4Z"),
  back: line("M9.5 3.5 5 8l4.5 4.5"),
  forward: line("M6.5 3.5 11 8l-4.5 4.5"),
  loop: line("M11 1.8 13.2 4 11 6.2M2.8 7.5V6a2 2 0 0 1 2-2h8.4M5 14.2 2.8 12 5 9.8M13.2 8.5V10a2 2 0 0 1-2 2H2.8"),
  loading: line("M8 2.5A5.5 5.5 0 1 0 13.5 8", "animate-spin motion-reduce:animate-none"),
};

const buttonClass =
  "inline-flex size-8 shrink-0 items-center justify-center rounded-md outline-none transition-colors select-none disabled:pointer-events-none disabled:opacity-40 motion-reduce:transition-none pointer-coarse:h-11 [&_svg]:size-4";

/** An icon button with its name in a tooltip. */
export const PlaybackButton = forwardRef<HTMLButtonElement, ButtonProps>(function PlaybackButton({ label, icon, pressed, className, ...props }, ref) {
  const { container } = usePlaybackControls();
  return (
    <Tooltip.Root>
      <Tooltip.Trigger
        render={
          <button
            ref={ref}
            type="button"
            aria-label={label}
            aria-pressed={pressed}
            className={cn(buttonClass, "text-muted-foreground hover:bg-foreground/10 hover:text-foreground focus-visible:bg-foreground/10 focus-visible:text-foreground aria-pressed:bg-primary/10 aria-pressed:text-foreground", className)}
            {...props}
          >
            {icon}
          </button>
        }
      />
      <Tooltip.Portal container={container ?? undefined}>
        <Tooltip.Positioner side="top" sideOffset={6} className="z-50">
          <Tooltip.Popup className="rounded-md bg-foreground px-2 py-1 text-xs whitespace-nowrap text-background shadow-md pointer-coarse:hidden">{label}</Tooltip.Popup>
        </Tooltip.Positioner>
      </Tooltip.Portal>
    </Tooltip.Root>
  );
});

/** Plays and pauses. It becomes Replay at the end, and shows a spinner while loading. */
export const PlaybackPlayButton = forwardRef<HTMLButtonElement, PartProps>(function PlaybackPlayButton({ className, onClick, ...props }, ref) {
  const { playing, ended, loading, disabled, messages, togglePlaying } = usePlaybackControls();
  const [label, icon] = loading ? [messages.loading, icons.loading] : ended ? [messages.replay, icons.replay] : playing ? [messages.pause, icons.pause] : [messages.play, icons.play];
  return (
    <PlaybackButton
      ref={ref}
      data-slot="playback-play"
      label={label}
      icon={icon}
      disabled={disabled || loading}
      className={cn("size-9 rounded-full bg-primary text-primary-foreground pointer-coarse:size-11 hover:bg-primary/90 hover:text-primary-foreground focus-visible:bg-primary focus-visible:text-primary-foreground focus-visible:ring-2 focus-visible:ring-primary/40", className)}
      onClick={(event) => {
        onClick?.(event);
        if (!event.defaultPrevented) togglePlaying();
      }}
      {...props}
    />
  );
});

/** Returns to the start. Playback keeps its current state. */
export const PlaybackRestartButton = forwardRef<HTMLButtonElement, PartProps>(function PlaybackRestartButton({ onClick, ...props }, ref) {
  const { seekable, messages, restart } = usePlaybackControls();
  return (
    <PlaybackButton
      ref={ref}
      data-slot="playback-restart"
      label={messages.restart}
      icon={icons.restart}
      disabled={!seekable}
      onClick={(event) => {
        onClick?.(event);
        if (!event.defaultPrevented) restart();
      }}
      {...props}
    />
  );
});

type StepProps = PartProps & {
  direction: "back" | "forward";
  /** Large is Rewind and Fast forward. Small steps finely, such as frame by frame. */
  size?: "large" | "small";
};

/** Moves back or forward: by largeStep as Rewind and Fast forward, or by step when small. */
export const PlaybackStepButton = forwardRef<HTMLButtonElement, StepProps>(function PlaybackStepButton({ direction, size = "large", onClick, ...props }, ref) {
  const { seekable, messages, stepBy } = usePlaybackControls();
  const back = direction === "back";
  const large = size === "large";
  return (
    <PlaybackButton
      ref={ref}
      data-slot="playback-step"
      label={large ? (back ? messages.rewind : messages.fastForward) : back ? messages.stepBack : messages.stepForward}
      icon={large ? (back ? icons.rewind : icons.fastForward) : back ? icons.back : icons.forward}
      disabled={!seekable}
      onClick={(event) => {
        onClick?.(event);
        if (!event.defaultPrevented) stepBy(back ? -1 : 1, size);
      }}
      {...props}
    />
  );
});

/** Turns looping on and off. It shows only when your app passes loop. */
export const PlaybackLoopButton = forwardRef<HTMLButtonElement, PartProps>(function PlaybackLoopButton({ onClick, ...props }, ref) {
  const { loop, disabled, messages, setLoop } = usePlaybackControls();
  if (loop === undefined) return null;
  return (
    <PlaybackButton
      ref={ref}
      data-slot="playback-loop"
      label={messages.loop}
      icon={icons.loop}
      pressed={loop}
      disabled={disabled}
      onClick={(event) => {
        onClick?.(event);
        if (!event.defaultPrevented) setLoop(!loop);
      }}
      {...props}
    />
  );
});

/** The speeds to offer, always including the current one. */
export const speedChoices = (speed: number, speeds: number[]) => (speeds.includes(speed) ? speeds : [...speeds, speed].sort((a, b) => a - b));

/** A menu of playback speeds. It shows only when your app passes speed. */
export const PlaybackSpeed = forwardRef<HTMLDivElement, Omit<ComponentPropsWithoutRef<"div">, "children">>(function PlaybackSpeed({ className, style, ...props }, ref) {
  const { speed, speeds, disabled, container, messages, setSpeed } = usePlaybackControls();
  if (speed === undefined) return null;
  const choices = speedChoices(speed, speeds);
  return (
    <InspectorField
      ref={ref}
      data-slot="playback-speed"
      label={messages.speed}
      align="start"
      disabled={disabled}
      className={cn("block w-20", className)}
      style={{ "--uicoolkit-field-height": "2rem", ...style } as ComponentPropsWithoutRef<"div">["style"]}
      {...props}
    >
      {/* Names the menu for screen readers; its current choice says enough on screen. */}
      <InspectorFieldLabel className="sr-only" />
      <InspectorFieldSelect
        value={String(speed)}
        options={choices.map((choice) => ({ value: String(choice), label: messages.speedValue(choice) }))}
        container={container}
        positionMethod={container ? "fixed" : undefined}
        onCommit={(next) => setSpeed(Number(next))}
      />
    </InspectorField>
  );
});

"use client";

import { Tooltip } from "@base-ui/react/tooltip";
import { type ComponentPropsWithoutRef, type KeyboardEvent, forwardRef, useRef, useState } from "react";
import { usePlaybackScrub } from "./playback-controls-scrub";
import { PlaybackSeek, PlaybackTime } from "./playback-controls-seek";
import { PlaybackTransport } from "./playback-controls-settings";
import { type PlaybackControlsProps, type PlaybackSeekDetail, PlaybackControlsContext, defaultMessages, defaultSpeeds } from "./playback-controls-state";
import { clampTime, formatPlaybackTime } from "./playback-controls-time";
import { cn } from "@/lib/utils";

/** Lays parts out in a line. Use one per row when composing your own controls. */
export const PlaybackControlsRow = forwardRef<HTMLDivElement, ComponentPropsWithoutRef<"div">>(function PlaybackControlsRow({ className, ...props }, ref) {
  return <div ref={ref} data-slot="playback-controls-row" className={cn("flex flex-wrap items-center gap-1", className)} {...props} />;
});

/** Transport controls for playback your app runs. Without children it shows every part your props support. */
export const PlaybackControls = forwardRef<HTMLDivElement, PlaybackControlsProps>(function PlaybackControls(
  {
    label,
    playing,
    onPlayingChange,
    currentTime,
    duration,
    onSeekCommit,
    onSeek,
    onScrubbingChange,
    step = 0.1,
    largeStep = 1,
    volume,
    onVolumeChange,
    onVolumeCommit,
    muted = false,
    onMutedChange,
    loop,
    onLoopChange,
    speed,
    onSpeedChange,
    speeds = defaultSpeeds,
    formatTime = formatPlaybackTime,
    loading = false,
    disabled = false,
    container,
    messages: messageOverrides,
    className,
    children,
    ...props
  },
  ref,
) {
  const messages = { ...defaultMessages, ...messageOverrides };
  const [live, setLive] = useState<number | null>(null);
  const trackRef = useRef<HTMLDivElement>(null);
  const thumbRef = useRef<HTMLDivElement>(null);
  const length = duration !== null && duration > 0 ? duration : 0;
  const seekable = !disabled && !loading && length > 0;
  const current = clampTime(currentTime, length);
  const time = live ?? current;
  const ended = length > 0 && !loop && time >= length;
  const { scrubbing, pointerFocus, setPointerFocus, seekHandlers, isScrubbing } = usePlaybackScrub({ time: current, duration: length, enabled: seekable, trackRef, thumbRef, setLive, onSeek, onSeekCommit, onScrubbingChange });

  const [liveVolume, setLiveVolume] = useState<number | null>(null);
  const volumeTrackRef = useRef<HTMLDivElement>(null);
  const volumeThumbRef = useRef<HTMLDivElement>(null);
  const savedVolume = clampTime(volume ?? 0, 1);
  const level = liveVolume ?? (muted ? 0 : savedVolume);
  const commitVolume = (next: number) => {
    onVolumeCommit?.(next);
    if (muted && next > 0) onMutedChange?.(false);
  };
  // The volume slider drags exactly like the seek bar, over a length of 1.
  const volumeDrag = usePlaybackScrub({
    time: savedVolume,
    duration: 1,
    enabled: !disabled && volume !== undefined,
    trackRef: volumeTrackRef,
    thumbRef: volumeThumbRef,
    setLive: setLiveVolume,
    onSeek: (next) => onVolumeChange?.(next),
    onSeekCommit: commitVolume,
  });

  const onVolumeKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    const amount = event.shiftKey ? 0.2 : 0.05;
    const targets: Record<string, number> = { ArrowLeft: level - amount, ArrowDown: level - amount, ArrowRight: level + amount, ArrowUp: level + amount, PageDown: level - 0.2, PageUp: level + 0.2, Home: 0, End: 1 };
    const raw = targets[event.key];
    if (raw === undefined || disabled) return;
    event.preventDefault();
    volumeDrag.setPointerFocus(false);
    const target = clampTime(raw, 1);
    if (target === level || volumeDrag.isScrubbing()) return;
    onVolumeChange?.(target);
    commitVolume(target);
  };

  const seekTo = (next: number, source: PlaybackSeekDetail["source"]) => {
    const target = clampTime(next, length);
    if (!seekable || isScrubbing() || target === current) return;
    onSeek?.(target, { source });
    onSeekCommit(target, { source });
  };

  const onSeekKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    const amount = event.shiftKey ? largeStep : step;
    const targets: Record<string, number> = {
      ArrowLeft: current - amount,
      ArrowDown: current - amount,
      ArrowRight: current + amount,
      ArrowUp: current + amount,
      PageDown: current - largeStep,
      PageUp: current + largeStep,
      Home: 0,
      End: length,
    };
    const target = targets[event.key];
    if (target === undefined || !seekable) return;
    event.preventDefault();
    setPointerFocus(false);
    seekTo(target, "keyboard");
  };

  const togglePlaying = () => {
    if (disabled || loading) return;
    if (!ended) return onPlayingChange(!playing);
    seekTo(0, "replay");
    onPlayingChange(true);
  };

  return (
    <PlaybackControlsContext.Provider
      value={{
        playing,
        time,
        duration: length > 0 ? length : null,
        seekable,
        ended,
        scrubbing,
        pointerFocus,
        loop,
        speed,
        speeds,
        loading,
        disabled,
        container,
        messages,
        formatTime,
        trackRef,
        thumbRef,
        seekHandlers,
        onSeekKeyDown,
        onThumbBlur: () => setPointerFocus(false),
        volumeState:
          volume === undefined
            ? null
            : {
                level,
                muted,
                dragging: volumeDrag.scrubbing,
                pointerFocus: volumeDrag.pointerFocus,
                trackRef: volumeTrackRef,
                thumbRef: volumeThumbRef,
                handlers: volumeDrag.seekHandlers,
                onKeyDown: onVolumeKeyDown,
                onThumbBlur: () => volumeDrag.setPointerFocus(false),
              },
        togglePlaying,
        restart: () => seekTo(0, "restart"),
        stepBy: (direction, size) => seekTo(current + direction * (size === "large" ? largeStep : step), "step"),
        setLoop: (next) => onLoopChange?.(next),
        setSpeed: (next) => onSpeedChange?.(next),
      }}
    >
      <Tooltip.Provider delay={400}>
        <div ref={ref} role="group" aria-label={label} aria-busy={loading || undefined} data-slot="playback-controls" data-disabled={disabled ? "" : undefined} className={cn("@container/playback grid w-full min-w-0 gap-1", className)} {...props}>
          {children ?? (
            <>
              {/* Together when wide. On phones and in narrow spaces, the times sit at either end of the bar. */}
              <PlaybackControlsRow className="flex-nowrap gap-3 max-sm:gap-2 max-sm:px-3 @max-xs/playback:gap-2 @max-xs/playback:px-3">
                <PlaybackTime show="current" className="hidden max-sm:inline @max-xs/playback:inline" />
                <PlaybackSeek />
                <PlaybackTime show="duration" className="hidden max-sm:inline @max-xs/playback:inline" />
                <PlaybackTime className="max-sm:hidden @max-xs/playback:hidden" />
              </PlaybackControlsRow>
              <PlaybackTransport />
            </>
          )}
        </div>
      </Tooltip.Provider>
    </PlaybackControlsContext.Provider>
  );
});

"use client";

import { type PointerEvent, useCallback, useEffect, useRef, useState } from "react";
import { type PlaybackSeekDetail, useIsomorphicLayoutEffect } from "./playback-controls-state";
import { clampTime } from "./playback-controls-time";

type Options = {
  time: number;
  duration: number;
  enabled: boolean;
  trackRef: { current: HTMLDivElement | null };
  thumbRef: { current: HTMLDivElement | null };
  setLive: (time: number | null) => void;
  onSeek?: (time: number, detail: PlaybackSeekDetail) => void;
  onSeekCommit: (time: number, detail: PlaybackSeekDetail) => void;
  onScrubbingChange?: (scrubbing: boolean) => void;
};

type Scrub = { id: number; start: number; last: number; element: HTMLElement };

const detail: PlaybackSeekDetail = { source: "pointer" };

/** Press the seek bar to jump, drag to scrub and press Escape to return to the start. */
export function usePlaybackScrub(options: Options) {
  const [scrubbing, setScrubbing] = useState(false);
  const [pointerFocus, setPointerFocus] = useState(false);
  const scrub = useRef<Scrub | null>(null);
  const latest = useRef(options);
  useIsomorphicLayoutEffect(() => {
    latest.current = options;
  });

  const update = useCallback((active: Scrub, clientX: number, clientY: number) => {
    const { duration, trackRef, setLive, onSeek } = latest.current;
    const track = trackRef.current;
    const box = track?.getBoundingClientRect();
    if (!track || !box || box.width === 0 || box.height === 0) return;
    // A vertical track fills from the bottom.
    const ratio = track.dataset.orientation === "vertical" ? 1 - (clientY - box.top) / box.height : (clientX - box.left) / box.width;
    const next = clampTime(Math.round(ratio * duration * 100) / 100, duration);
    if (next === active.last) return;
    active.last = next;
    setLive(next);
    onSeek?.(next, detail);
  }, []);

  const finish = useCallback((cancel: boolean) => {
    const active = scrub.current;
    if (!active) return;
    scrub.current = null;
    const { setLive, onSeek, onSeekCommit, onScrubbingChange } = latest.current;
    const changed = active.start !== active.last;
    if (changed && cancel) onSeek?.(active.start, detail);
    if (changed && !cancel) onSeekCommit(active.last, detail);
    setLive(null);
    setScrubbing(false);
    onScrubbingChange?.(false);
    if (active.element.hasPointerCapture?.(active.id)) active.element.releasePointerCapture(active.id);
  }, []);

  useEffect(() => {
    if (!scrubbing) return;
    const onKey = (event: KeyboardEvent) => {
      if (event.key !== "Escape") return;
      event.preventDefault();
      event.stopPropagation();
      finish(true);
    };
    const onBlur = () => finish(true);
    const onPointerEnd = (event: globalThis.PointerEvent) => {
      if (scrub.current?.id === event.pointerId) finish(event.type === "pointercancel");
    };
    window.addEventListener("keydown", onKey, true);
    window.addEventListener("blur", onBlur);
    window.addEventListener("pointerup", onPointerEnd);
    window.addEventListener("pointercancel", onPointerEnd);
    return () => {
      window.removeEventListener("keydown", onKey, true);
      window.removeEventListener("blur", onBlur);
      window.removeEventListener("pointerup", onPointerEnd);
      window.removeEventListener("pointercancel", onPointerEnd);
    };
  }, [scrubbing, finish]);

  useEffect(() => () => finish(true), [finish]);

  const seekHandlers = {
    onPointerDown: (event: PointerEvent<HTMLDivElement>) => {
      if (event.defaultPrevented || event.button !== 0 || !options.enabled || scrub.current) return;
      event.preventDefault();
      const active: Scrub = { id: event.pointerId, start: options.time, last: options.time, element: event.currentTarget };
      scrub.current = active;
      try {
        event.currentTarget.setPointerCapture?.(event.pointerId);
      } catch {
        // The pointer may already have ended; the window listener still finishes the drag.
      }
      setPointerFocus(true);
      options.thumbRef.current?.focus({ preventScroll: true });
      setScrubbing(true);
      options.onScrubbingChange?.(true);
      update(active, event.clientX, event.clientY);
    },
    onPointerMove: (event: PointerEvent<HTMLDivElement>) => {
      const active = scrub.current;
      if (active?.id === event.pointerId) update(active, event.clientX, event.clientY);
    },
    onPointerUp: (event: PointerEvent<HTMLDivElement>) => {
      if (scrub.current?.id === event.pointerId) finish(false);
    },
    onPointerCancel: (event: PointerEvent<HTMLDivElement>) => {
      if (scrub.current?.id === event.pointerId) finish(true);
    },
    onLostPointerCapture: (event: PointerEvent<HTMLDivElement>) => {
      if (scrub.current?.id === event.pointerId) finish(true);
    },
  };

  return { scrubbing, pointerFocus, setPointerFocus, seekHandlers, isScrubbing: () => scrub.current !== null };
}

"use client";

import { type ComponentPropsWithoutRef, type KeyboardEvent, forwardRef } from "react";
import { type PlaybackVolumeState, usePlaybackControls } from "./playback-controls-state";
import { cn } from "@/lib/utils";

type DivProps = Omit<ComponentPropsWithoutRef<"div">, "children">;
type SliderProps = DivProps & {
  slot: string;
  name: string;
  orientation?: "horizontal" | "vertical";
  /** Position along the track, from 0 to 1. */
  ratio: number;
  max: number;
  now: number;
  text: string;
  enabled: boolean;
  blocked: boolean;
  active: boolean;
  pointerFocus: boolean;
  trackRef: { current: HTMLDivElement | null };
  thumbRef: { current: HTMLDivElement | null };
  handlers: PlaybackVolumeState["handlers"];
  onThumbKeyDown: (event: KeyboardEvent<HTMLDivElement>) => void;
  onThumbBlur: () => void;
};

const both = <Event,>(own: ((event: Event) => void) | undefined, next: (event: Event) => void) => (event: Event) => {
  own?.(event);
  next(event);
};

/** The track and thumb shared by the seek bar and the volume slider. */
export const PlaybackSlider = forwardRef<HTMLDivElement, SliderProps>(function PlaybackSlider(
  { slot, name, orientation = "horizontal", ratio, max, now, text, enabled, blocked, active, pointerFocus, trackRef, thumbRef, handlers, onThumbKeyDown, onThumbBlur, className, onPointerDown, onPointerMove, onPointerUp, onPointerCancel, onLostPointerCapture, ...props },
  ref,
) {
  const position = `${ratio * 100}%`;
  const vertical = orientation === "vertical";
  return (
    <div
      ref={ref}
      data-slot={slot}
      data-scrubbing={active ? "" : undefined}
      className={cn(
        "flex select-none",
        vertical ? "h-28 w-6 touch-pan-x flex-col items-center" : "h-6 min-w-0 touch-pan-y items-center pointer-coarse:h-11",
        enabled ? "cursor-pointer" : "opacity-50",
        blocked && "cursor-not-allowed",
        className,
      )}
      onPointerDown={both(onPointerDown, handlers.onPointerDown)}
      onPointerMove={both(onPointerMove, handlers.onPointerMove)}
      onPointerUp={both(onPointerUp, handlers.onPointerUp)}
      onPointerCancel={both(onPointerCancel, handlers.onPointerCancel)}
      onLostPointerCapture={both(onLostPointerCapture, handlers.onLostPointerCapture)}
      {...props}
    >
      <div ref={trackRef} data-slot={`${slot}-track`} data-orientation={orientation} className={cn("relative flex-1 rounded-full bg-foreground/15", vertical ? "my-1.5 w-1" : "mx-1.5 h-1")}>
        <div data-slot={`${slot}-fill`} className={cn("absolute rounded-full bg-primary", vertical ? "inset-x-0 bottom-0" : "inset-y-0 left-0")} style={vertical ? { height: position } : { width: position }} />
        <div
          ref={thumbRef}
          role="slider"
          tabIndex={enabled ? 0 : undefined}
          aria-label={name}
          aria-orientation={orientation}
          aria-valuemin={0}
          aria-valuemax={max}
          aria-valuenow={now}
          aria-valuetext={text}
          aria-disabled={!enabled || undefined}
          data-slot={`${slot}-thumb`}
          data-active={active ? "" : undefined}
          data-pointer-focus={pointerFocus ? "" : undefined}
          className={cn(
            "absolute size-3 -translate-x-1/2 rounded-full bg-primary shadow-sm outline-none transition-[scale,box-shadow] duration-100 ease-out data-active:scale-125 data-active:ring-4 data-active:ring-primary/25 motion-reduce:transition-none [&:focus-visible:not([data-pointer-focus])]:ring-2 [&:focus-visible:not([data-pointer-focus])]:ring-primary/40",
            vertical ? "left-1/2 translate-y-1/2" : "top-1/2 -translate-y-1/2",
          )}
          style={vertical ? { bottom: position } : { left: position }}
          onKeyDown={onThumbKeyDown}
          onBlur={onThumbBlur}
        />
      </div>
    </div>
  );
});

/** The bar you press to jump and drag to scrub. Its thumb holds keyboard focus. */
export const PlaybackSeek = forwardRef<HTMLDivElement, DivProps>(function PlaybackSeek({ className, ...props }, ref) {
  const { time, duration, seekable, disabled, scrubbing, pointerFocus, messages, formatTime, trackRef, thumbRef, seekHandlers, onSeekKeyDown, onThumbBlur } = usePlaybackControls();
  const total = duration === null ? messages.unknownTime : formatTime(duration);
  return (
