  level: number;
  muted: boolean;
  dragging: boolean;
  pointerFocus: boolean;
  trackRef: { current: HTMLDivElement | null };
  thumbRef: { current: HTMLDivElement | null };
  handlers: SliderHandlers;
  onKeyDown: (event: KeyboardEvent<HTMLDivElement>) => void;
  onThumbBlur: () => void;
